"use client";

import * as DialogPrimitive from "@radix-ui/react-dialog";
import { createContext, useCallback, useContext, useMemo, useRef, useState } from "react";
import type { ComponentPropsWithoutRef, ReactNode, RefObject } from "react";
import { AnimatePresence, animate, motion, useMotionValue, useReducedMotion } from "motion/react";
import type { PanInfo, Transition } from "motion/react";
import { X } from "lucide-react";
import { ESCAPE_LAYER_ATTRIBUTE, layerEscape } from "../lib/escape";
import { motionTokens } from "../lib/motion-tokens";
import { useReturnFocus } from "../lib/return-focus";
import styles from "./drawer.module.css";

/**
 * The last item a drawer showed. Pass the selected item (or null when nothing is open) and render the drawer's content
 * from the result, so the content stays on screen while the panel slides out instead of vanishing the moment it closes.
 */
export function useDrawerItem<T>(item: T | null | undefined): T | null | undefined {
  const [last, setLast] = useState(item);
  if (item != null && item !== last) setLast(item);
  return item ?? last;
}

/** Mirrors the open state so the panel can stay mounted while it slides out, retarget mid-flight, and close itself after a drag. */
const DrawerContext = createContext<{ open: boolean; flung: boolean; setOpen: (open: boolean) => void; fling: () => void; openedAt: RefObject<number> } | null>(null);

export function Drawer({ open: openProp, defaultOpen = false, onOpenChange, ...props }: ComponentPropsWithoutRef<typeof DialogPrimitive.Root>) {
  const [uncontrolled, setUncontrolled] = useState(defaultOpen);
  // A drag that dismisses the panel hands its velocity to the exit spring; every other close uses the shorter tween.
  const [flung, setFlung] = useState(false);
  // When the drawer last opened, so a click that reopens it mid-close is not also read as a click outside the leaving panel.
  const openedAt = useRef(0);
  const open = openProp ?? uncontrolled;
  const setOpen = useCallback((next: boolean) => {
    setFlung(false);
    if (next) openedAt.current = performance.now();
    if (openProp === undefined) setUncontrolled(next);
    onOpenChange?.(next);
  }, [openProp, onOpenChange]);
  const fling = useCallback(() => { setOpen(false); setFlung(true); }, [setOpen]);
  const value = useMemo(() => ({ open, flung, setOpen, fling, openedAt }), [open, flung, setOpen, fling]);
  return <DrawerContext.Provider value={value}><DialogPrimitive.Root {...props} open={open} onOpenChange={setOpen} /></DrawerContext.Provider>;
}

export const DrawerTrigger = DialogPrimitive.Trigger;
export const DrawerClose = DialogPrimitive.Close;

export interface DrawerContentProps
  extends ComponentPropsWithoutRef<typeof DialogPrimitive.Content> {
  title: string;
  description?: string;
  children: ReactNode;
  side?: "left" | "right" | "top" | "bottom";
  /** Renders the drawer inside this element instead of the page body, anchored to its edges. The element needs position: relative and overflow: hidden. */
  container?: HTMLElement | null;
}

const fade: Transition = { duration: motionTokens.duration.instant };
/* A click or Escape returns the panel quickly; a flick keeps its velocity in a spring of the same length. The shadow fades over the last stretch so it leaves with the panel instead of popping away at unmount. */
const shadowOut: Transition = { duration: motionTokens.duration.standard, times: [0, .65, 1], ease: "linear" };
const leave: Transition = { default: { duration: motionTokens.duration.standard, ease: [...motionTokens.ease.standard] }, opacity: shadowOut };
const flingOut: Transition = { default: { ...motionTokens.spring.smooth, visualDuration: motionTokens.duration.standard }, opacity: shadowOut };

/** When the title or description changes while open, the new copy rises in and the old copy leaves upward. */
function SwapText({ text }: { text: string }) {
  const reduced = useReducedMotion();
  return (
    <AnimatePresence mode="popLayout" initial={false}>
      <motion.span
        key={text}
        className={styles.swap}
        initial={reduced ? false : { opacity: 0, y: "0.3em", filter: `blur(${motionTokens.blur.soft}px)` }}
        animate={{ opacity: 1, y: 0, filter: "blur(0px)" }}
        exit={reduced ? { opacity: 0, transition: { duration: 0 } } : { opacity: 0, y: "-0.3em", filter: `blur(${motionTokens.blur.subtle}px)`, transition: { duration: motionTokens.duration.fast, ease: [...motionTokens.ease.standard] } }}
        transition={{ duration: motionTokens.duration.standard, ease: [...motionTokens.ease.enter] }}
      >
        {text}
      </motion.span>
    </AnimatePresence>
  );
}

export function DrawerContent({
  title,
  description,
  children,
  side = "right",
  container,
  className,
  onInteractOutside,
  onEscapeKeyDown,
  onOpenAutoFocus,
  onCloseAutoFocus,
  ...props
}: DrawerContentProps) {
  const drawer = useContext(DrawerContext);
  const reduced = useReducedMotion();
  // Closing puts focus back on what opened the drawer, Trigger or not (lib/return-focus.ts).
  const returnFocus = useReturnFocus(drawer?.open, onOpenAutoFocus, onCloseAutoFocus);
  // Escape inside belongs to an open list, calendar or question first (lib/escape.ts); the next one closes the drawer.
  const escape = { [ESCAPE_LAYER_ATTRIBUTE]: "", onEscapeKeyDown: layerEscape(onEscapeKeyDown), ...returnFocus };
  const panelRef = useRef<HTMLDivElement>(null);
  const offset = useMotionValue<number | string>(0);
  const pan = useRef<number | null>(null);
  const axis = side === "left" || side === "right" ? "x" : "y";
  const sign = side === "right" || side === "bottom" ? 1 : -1;
  const offscreen = { [axis]: `${sign * 100}%` };
  const classes = [styles.content, className].filter(Boolean).join(" ");
  const draggable = drawer !== null && !reduced;

  const panelSize = () => (axis === "x" ? panelRef.current?.offsetWidth : panelRef.current?.offsetHeight) ?? 480;

  // The header is the grab handle. It follows the pointer toward the edge and rubber-bands the other way.
  function panStart(event: PointerEvent) {
    const target = event.target instanceof Element ? event.target : null;
    if (!draggable || target?.closest("button, a, input, select, textarea, [role='button']")) return;
    // The entrance animates in percent of the panel, so a grab mid-flight converts it to pixels.
    const value = offset.get();
    pan.current = typeof value === "number" ? value : parseFloat(value) / 100 * panelSize();
    offset.stop();
  }
  function panMove(_: PointerEvent, info: PanInfo) {
    if (pan.current === null) return;
    const toward = (pan.current + info.offset[axis]) * sign;
    offset.set(sign * (toward >= 0 ? toward : -Math.sqrt(-toward)));
  }
  // Past a third of the panel, or on a quick flick toward the edge, the drawer closes and keeps its velocity; otherwise it springs back.
  function panEnd(_: PointerEvent, info: PanInfo) {
    if (pan.current === null) return;
    pan.current = null;
    const toward = Number(offset.get()) * sign;
    if (toward > panelSize() / 3 || (toward > 0 && info.velocity[axis] * sign > 500)) drawer?.fling();
    else animate(offset, 0, motionTokens.spring.snappy);
  }

  const inner = <>
    <motion.div className={[styles.header, draggable ? styles.handle : ""].filter(Boolean).join(" ")} onPanStart={panStart} onPan={panMove} onPanEnd={panEnd}>
      <div>
        <DialogPrimitive.Title className={styles.title}><SwapText text={title} /></DialogPrimitive.Title>
        {description ? (
          <DialogPrimitive.Description className={styles.description}>
            <SwapText text={description} />
          </DialogPrimitive.Description>
        ) : null}
      </div>
      <DialogPrimitive.Close className={styles.close} aria-label="Close drawer">
        <X size={16} strokeWidth={1.75} aria-hidden="true" />
      </DialogPrimitive.Close>
    </motion.div>
    <div className={styles.body}>{children}</div>
  </>;

  // Under a bare Radix root the open state is unknown here, so CSS keyframes keyed off data-state animate the layers instead.
  if (drawer === null) {
    return (
      <DialogPrimitive.Portal container={container}>
        <DialogPrimitive.Overlay className={`${styles.overlay} ${styles.keyframes}`} data-contained={container ? "" : undefined} />
        <DialogPrimitive.Content {...props} {...escape} onInteractOutside={onInteractOutside} data-side={side} data-contained={container ? "" : undefined} className={`${classes} ${styles.keyframes}`}>{inner}</DialogPrimitive.Content>
      </DialogPrimitive.Portal>
    );
  }

  // The panel springs fully opaque from its own edge and returns to it faster than it arrived, from wherever it is.
  return (
    <AnimatePresence custom={drawer.flung}>
      {drawer.open && (
        <DialogPrimitive.Portal key="drawer" forceMount container={container}>
          <DialogPrimitive.Overlay asChild forceMount>
            <motion.div
              className={styles.overlay}
              data-contained={container ? "" : undefined}
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0, transition: reduced ? fade : { duration: motionTokens.duration.fast, ease: [...motionTokens.ease.standard] } }}
              transition={reduced ? fade : { duration: motionTokens.duration.standard, ease: [...motionTokens.ease.enter] }}
            />
          </DialogPrimitive.Overlay>
          <DialogPrimitive.Content
            {...props}
            {...escape}
            asChild
            forceMount
            // Radix reads a click outside on click, so the press that reopens a closing drawer would dismiss it again.
            onInteractOutside={event => {
              onInteractOutside?.(event);
              if (event.detail.originalEvent.timeStamp < drawer.openedAt.current) event.preventDefault();
            }}
          >
            <motion.div
              ref={panelRef}
              className={classes}
              data-side={side}
              data-contained={container ? "" : undefined}
              style={{ [axis]: offset }}
              variants={{ exit: (flung: boolean) => reduced ? { opacity: 0, transition: fade } : { ...offscreen, opacity: [1, 1, 0], transition: flung ? flingOut : leave } }}
              initial={reduced ? { opacity: 0 } : { ...offscreen, opacity: 1 }}
              animate={reduced ? { opacity: 1 } : { [axis]: 0, opacity: 1 }}
              exit="exit"
              transition={reduced ? fade : motionTokens.spring.smooth}
            >
              {inner}
            </motion.div>
          </DialogPrimitive.Content>
        </DialogPrimitive.Portal>
      )}
    </AnimatePresence>
  );
}

export default Drawer;

.overlay {
  position: fixed;
  inset: 0;
  z-index: var(--layer-overlay);
  background: var(--scrim);
  backdrop-filter: blur(4px);
}

.content {
  --drawer-size: min(30rem, calc(100vw - var(--space-inset)));
  /* Critically damped, like a sheet spring: it never overshoots past the edge it is anchored to. */
  --ease-drawer: cubic-bezier(.32,.72,0,1);
  --drawer-from: translateX(100%);
  position: fixed;
  z-index: var(--layer-dialog);
  display: flex;
  flex-direction: column;
  width: var(--drawer-size);
  max-width: 100vw;
  max-height: 100dvh;
  overflow: hidden;
  border: 1px solid var(--border);
  background: var(--surface-raised);
  color: var(--foreground);
  box-shadow: var(--shadow-floating);
}
/* While a layer leaves it lets clicks through, so pressing the trigger again during the close reopens the drawer from wherever it is. */
/* Radix writes pointer-events inline on the overlay, so the closing state has to win over it. */
.overlay[data-state="closed"], .content[data-state="closed"] { pointer-events: none !important; }

.content[data-side="right"] { inset: 0 0 0 auto; border-width: 1px 0 1px 1px; border-radius: var(--radius-container) 0 0 var(--radius-container); corner-shape: var(--corner-shape); }
.content[data-side="left"] { inset: 0 auto 0 0; border-width: 1px 1px 1px 0; border-radius: 0 var(--radius-container) var(--radius-container) 0; corner-shape: var(--corner-shape); }
.content[data-side="top"] { inset: 0 0 auto; width: 100%; max-width: none; max-height: min(32rem, 100dvh); border-width: 0 0 1px; border-radius: 0 0 var(--radius-container) var(--radius-container); corner-shape: var(--corner-shape); }
.content[data-side="bottom"] { inset: auto 0 0; width: 100%; max-width: none; max-height: min(32rem, 100dvh); border-width: 1px 0 0; border-radius: var(--radius-container) var(--radius-container) 0 0; corner-shape: var(--corner-shape); }
.content[data-side="bottom"]::before { position: absolute; top: var(--space-related); left: 50%; width: 2.25rem; height: 4px; border-radius: var(--radius-full); corner-shape: round; background: var(--border-strong); content: ""; opacity: .75; transform: translateX(-50%); }

/* Motion springs the panel from its edge. Keyframes only run when DrawerContent sits under a bare Radix root. */
.content[data-side="left"] { --drawer-from: translateX(-100%); }
.content[data-side="top"] { --drawer-from: translateY(-100%); }
.content[data-side="bottom"] { --drawer-from: translateY(100%); }
.keyframes.overlay[data-state="open"] { animation: overlay-in var(--duration-standard) var(--ease-enter) both; }
.keyframes.overlay[data-state="closed"] { animation: overlay-out var(--duration-fast) var(--ease-standard) both; }
.keyframes.content[data-state="open"] { animation: drawer-in var(--duration-considered) var(--ease-drawer) both; }
.keyframes.content[data-state="closed"] { animation: drawer-out var(--duration-standard) var(--ease-standard) both; }
.content:focus { outline: none; }
/* Inside a container the layers anchor to that element instead of the viewport. */
.overlay[data-contained], .content[data-contained] { position: absolute; }
.overlay[data-contained] { z-index: 1; background: var(--scrim-soft); backdrop-filter: none; }
.content[data-contained] { --drawer-size: min(22rem, calc(100% - var(--space-block))); z-index: 2; max-height: 100%; box-shadow: none; }
.content[data-contained][data-side="top"], .content[data-contained][data-side="bottom"] { max-height: min(32rem, calc(100% - var(--space-block))); }
/* The container already draws the outer edges, so only the inner edge keeps a border. */
.content[data-contained][data-side] { border-width: 0; }
.content[data-contained][data-side="right"] { border-left-width: 1px; }
.content[data-contained][data-side="left"] { border-right-width: 1px; }
.content[data-contained][data-side="top"] { border-bottom-width: 1px; }
.content[data-contained][data-side="bottom"] { border-top-width: 1px; }

.header { display: flex; flex: 0 0 auto; align-items: flex-start; justify-content: space-between; gap: var(--space-comfort); padding: var(--space-section); border-bottom: 1px solid var(--border); }
/* The header doubles as the drag handle, so touch drags move the panel instead of the page. */
.handle { touch-action: none; user-select: none; }
.content[data-side="bottom"] .handle, .content[data-side="top"] .handle { cursor: grab; }
.title, .description { position: relative; }
/* The copy sets its own line height so a page-level heading rule cannot squeeze the title. */
.swap { display: block; line-height: var(--leading-body); }
.title { margin: 0; font-family: var(--font-body); font-size: var(--text-lg); font-weight: 500; letter-spacing: var(--tracking-body); line-height: var(--leading-body); }
.description { max-width: 32rem; margin: var(--space-related) 0 0; color: var(--text-secondary); font-size: var(--text-sm); line-height: var(--leading-body); }
/* Centered on the first line of the title rather than its top edge. */
.close { display: grid; flex: 0 0 auto; width: var(--space-block); height: var(--space-block); margin-top: calc((var(--text-lg) * var(--leading-body) - var(--space-block)) / 2); place-items: center; border: 1px solid var(--border); border-radius: var(--radius-control); corner-shape: var(--corner-shape); background: color-mix(in oklab, var(--surface-muted) 65%, transparent); color: var(--text-secondary); cursor: pointer; transition: background-color var(--duration-fast) var(--ease-standard), color var(--duration-fast) var(--ease-standard), transform var(--duration-spring) var(--ease-spring); }
@media (hover: hover) and (pointer: fine) { .close:hover { background: var(--surface-muted); color: var(--foreground); } }
.close:active { transform: scale(.96); transition: background-color var(--duration-fast) var(--ease-standard), color var(--duration-fast) var(--ease-standard), transform var(--duration-instant) var(--ease-standard); }
.body { min-height: 0; overflow: auto; padding: var(--space-section); font-size: var(--text-sm); line-height: var(--leading-body); overscroll-behavior: contain; scrollbar-width: thin; }

@media (max-width: 40rem) {
  .content { --drawer-size: calc(100vw - var(--space-group)); }
  .content[data-side="right"] { border-radius: var(--radius-control) 0 0 var(--radius-control); corner-shape: var(--corner-shape); }
  .content[data-side="left"] { border-radius: 0 var(--radius-control) var(--radius-control) 0; corner-shape: var(--corner-shape); }
  .content[data-side="top"] { border-radius: 0 0 var(--radius-control) var(--radius-control); corner-shape: var(--corner-shape); }
  .content[data-side="bottom"] { border-radius: var(--radius-control) var(--radius-control) 0 0; corner-shape: var(--corner-shape); }
  .header, .body { padding: var(--space-comfort); }
}

@keyframes overlay-in { from { opacity: 0; } }
@keyframes overlay-out { to { opacity: 0; } }
@keyframes drawer-in { from { transform: var(--drawer-from); } }
/* The late fade lets the floating shadow leave with the panel instead of popping away at unmount. */
@keyframes drawer-out { 65% { opacity: 1; } to { opacity: 0; transform: var(--drawer-from); } }
@keyframes drawer-fade-in { from { opacity: 0; } }
@keyframes drawer-fade-out { to { opacity: 0; } }

@media (prefers-reduced-motion: reduce) {
  .keyframes.overlay[data-state="open"] { animation: overlay-in var(--duration-instant) linear both; }
  .keyframes.overlay[data-state="closed"] { animation: overlay-out var(--duration-fast) linear both; }
  .keyframes.content[data-state="open"] { animation: drawer-fade-in var(--duration-instant) linear both; }
  .keyframes.content[data-state="closed"] { animation: drawer-fade-out var(--duration-fast) linear both; }
  .close, .close:active { transition: none; }
  .close:active { transform: none; }
}

/**
 * Escape inside a layer (Dialog, Drawer, BottomSheet, Popover) belongs to the control that has focus when that control
 * has something of its own to close: an open Combobox list, an open DatePicker calendar, an InlineEdit being edited, a
 * ConfirmMorph asking its question. Only the next Escape closes the layer.
 *
 * Radix closes its layers from a capture listener on the document, before the control's own key handler runs, so every
 * Silicon UI layer passes its `onEscapeKeyDown` through `layerEscape` (and marks its own panel with `data-escape-layer`, where
 * the search for an inner popup stops). Pages need nothing for this; their own `onEscapeKeyDown` still runs first and
 * can keep the layer open for reasons of its own with `event.preventDefault()`.
 */

/** Marks a layer's own panel (so it is never mistaken for a popup of a control inside it). */
export const ESCAPE_LAYER_ATTRIBUTE = "data-escape-layer";

/** Controls that close something of their own on Escape while focus is in them. */
const OWN_ESCAPE = [
  // Combobox with its list open (focus stays in its input).
  '[role="combobox"][aria-expanded="true"]',
  // DatePicker's trigger (or any popup button) while its panel is open.
  '[aria-haspopup="dialog"][aria-expanded="true"]',
  '[aria-haspopup="listbox"][aria-expanded="true"]',
  // InlineEdit while editing: Escape puts the saved text back.
  "[data-editing]",
].join(", ");

/** ConfirmMorph asking its question or showing a result (Escape returns it to rest). */
const MORPH_STATES = '[data-state="confirming"], [data-state="done"], [data-state="error"]';

/** True when Escape at `target` is handled by a control inside the layer, which closes its own part first. */
export function escapeBelongsInside(target: EventTarget | null): boolean {
  if (!(target instanceof Element)) return false;
  if (target.closest(OWN_ESCAPE)) return true;
  // A ConfirmMorph's root (focused while it works or shows a result) or one of its faces. A HoldToConfirm button also
  // says data-state="done", but it has no faces and no Escape of its own.
  const morph = target.closest(MORPH_STATES);
  if (morph?.querySelector("[data-face]")) return true;
  // A popup of a control (DatePicker's calendar is a dialog inside the layer); the layer's own panel is not one.
  const dialog = target.closest('[role="dialog"]');
  return !!dialog && !dialog.hasAttribute(ESCAPE_LAYER_ATTRIBUTE);
}

/**
 * The `onEscapeKeyDown` a Silicon UI layer gives Radix: the page's own handler first, then the layer stays open when the
 * Escape belongs to a control inside it.
 */
export function layerEscape<E extends KeyboardEvent>(own?: (event: E) => void): (event: E) => void {
  return event => {
    own?.(event);
    if (!event.defaultPrevented && escapeBelongsInside(event.target)) event.preventDefault();
  };
}

/**
 * Focus goes back to what opened a layer when it closes (WCAG 2.4.3), however it was opened.
 *
 * Radix's modal Dialog returns focus only to its own <Dialog.Trigger>. Most layers here open from controlled state (a
 * plain button, a menu item, a command, a key), so there is no Trigger and focus fell to <body> when they closed.
 * `useReturnFocus(open)` remembers what had focus when `open` turned true and hands the layer's content an
 * `onCloseAutoFocus` that puts focus back there:
 *
 * - it is captured in an insertion effect, which runs before anything in the layer can take focus (an `autoFocus`
 *   field is focused in the layout phase, Radix's FocusScope moves focus in a passive effect); under a bare Radix root,
 *   where `open` is unknown, `onOpenAutoFocus` captures it instead;
 * - the caller's own `onCloseAutoFocus` runs first, and one that calls `preventDefault()` keeps its own target;
 * - nothing remembered (focus was on <body>, or the element is gone): Radix's own behaviour, its Trigger if any;
 * - focus already moved on to something outside the layer while it left (a command opened another layer, a link was
 *   followed): it stays there.
 */
import { useInsertionEffect, useRef } from "react";

/** What has focus now, unless that is nothing in particular (<body>). */
function focusedElement(): HTMLElement | null {
  const active = typeof document === "undefined" ? null : document.activeElement;
  return active instanceof HTMLElement && active !== document.body ? active : null;
}

export interface ReturnFocusHandlers {
  onOpenAutoFocus: (event: Event) => void;
  onCloseAutoFocus: (event: Event) => void;
}

/**
 * `open`: the layer's open state (null or undefined when the caller cannot know it). `onOpenAutoFocus` /
 * `onCloseAutoFocus`: the caller's own handlers, composed (they run first).
 */
export function useReturnFocus(open: boolean | null | undefined, onOpenAutoFocus?: (event: Event) => void, onCloseAutoFocus?: (event: Event) => void): ReturnFocusHandlers {
  const opener = useRef<HTMLElement | null>(null);
  useInsertionEffect(() => {
    if (open) opener.current = focusedElement();
  }, [open]);
  return {
    onOpenAutoFocus(event) {
      if (open === null || open === undefined) opener.current = focusedElement();
      onOpenAutoFocus?.(event);
    },
    onCloseAutoFocus(event) {
      onCloseAutoFocus?.(event);
      const target = opener.current;
      opener.current = null;
      const layer = event.currentTarget instanceof Element ? event.currentTarget : null;
      if (event.defaultPrevented || !target?.isConnected || layer?.contains(target)) return;
      event.preventDefault();
      const active = document.activeElement;
      if (active && active !== document.body && !layer?.contains(active)) return;
      target.focus();
    },
  };
}
